class Grid {
  private cell: number
  private map = new Map<number, Blob[]>()

  constructor(cell: number) {
    this.cell = Math.max(24, cell)
  }

  private key(cx: number, cy: number) {
    return (cx + 4096) * 8192 + (cy + 4096)
  }

  insert(b: Blob) {
    const cx = Math.floor(b.x / this.cell)
    const cy = Math.floor(b.y / this.cell)
    const k = this.key(cx, cy)
    const bucket = this.map.get(k)
    if (bucket) bucket.push(b)
    else this.map.set(k, [b])
  }

  query(x: number, y: number, radius: number, fn: (b: Blob) => void) {
    const span = Math.ceil(radius / this.cell)
    const cx = Math.floor(x / this.cell)
    const cy = Math.floor(y / this.cell)
    for (let ix = cx - span; ix <= cx + span; ix++) {
      for (let iy = cy - span; iy <= cy + span; iy++) {
        const bucket = this.map.get(this.key(ix, iy))
        if (!bucket) continue
        for (const b of bucket) fn(b)
      }
    }
  }
}

function addEffect(world: World, e: Omit<Effect, 'maxLife'> & { maxLife?: number }) {
  if (world.effects.length > 260) world.effects.shift()
  world.effects.push({ ...e, maxLife: e.maxLife ?? e.life })
}

export function step(world: World, params: Params, rng: Rng) {
  const dt = DT
  world.t += dt
  world.steps++

  growFruit(world, params, dt)

  const visionCell = Math.max(params.blueVision, params.redVision, 40)
  const grid = new Grid(visionCell / 1.5)
  const shelter2 = CONST.shelterRadius * CONST.shelterRadius
  for (const b of world.blobs) {
    grid.insert(b)
    if (b.kind !== 'blue') continue
    b.sheltered = false
    for (const tree of world.trees) {
      const dx = tree.x - b.x
      const dy = tree.y - b.y
      if (dx * dx + dy * dy < shelter2) {
        b.sheltered = true
        break
      }
    }
  }

  const born: Blob[] = []

  for (const b of world.blobs) {
    b.px = b.x
    b.py = b.y
    b.age += dt
    if (b.copyCooldown > 0) b.copyCooldown -= dt
    if (b.immunity > 0) b.immunity -= dt
    if (b.panic > 0) b.panic -= dt
    if (b.glow > 0) b.glow = Math.max(0, b.glow - dt * 1.6)
    if (b.squash > 0) b.squash = Math.max(0, b.squash - dt * 3)

    if (b.actionTimer > 0) {
      b.actionTimer -= dt
      if (b.actionTimer <= 0) finishLockedAction(world, params, b, rng)
    }

    if (b.kind === 'blue') stepBlue(world, params, b, grid, rng, dt)
    else stepRed(world, params, b, grid, rng, dt)

    const base = b.kind === 'blue' ? params.blueSpeed : params.redSpeed
    const effort = base > 0 ? Math.hypot(b.vx, b.vy) / base : 0
    const jostle = b.kind === 'red' ? 1 + CONST.interferenceCost * b.crowding : 1
    const senses = 1 + CONST.visionCost * (b.traits.vision - 1)
    const upkeep = ((b.kind === 'blue' ? params.blueUpkeep : params.redUpkeep) * jostle * senses) / b.traits.thrift
    b.energy -= upkeep * (CONST.idleUpkeep + (1 - CONST.idleUpkeep) * effort * effort) * dt

    if (b.actionTimer <= 0 && b.copyCooldown <= 0) tryCopy(world, params, b, born, rng)
  }

  if (born.length) world.blobs.push(...born)

  const survivors: Blob[] = []
  for (const b of world.blobs) {
    const starved = b.energy <= 0
    const old = b.age >= b.lifespan
    if (starved || old) {
      world.totals.deaths[b.kind]++
      if (starved) world.totals.starved[b.kind]++
      else world.totals.aged[b.kind]++
      addEffect(world, { kind: 'death', x: b.x, y: b.y, z: 8, life: 0.75, color: b.kind, seed: b.id })
    } else {
      survivors.push(b)
    }
  }
  world.blobs = survivors

  for (let i = world.effects.length - 1; i >= 0; i--) {
    world.effects[i].life -= dt
    if (world.effects[i].life <= 0) world.effects.splice(i, 1)
  }

  recount(world)
  if (world.counts.blue === 0 && world.extinct.blue === null) world.extinct.blue = world.t
  if (world.counts.blue > 0) world.extinct.blue = null
  if (world.counts.red === 0 && world.extinct.red === null) world.extinct.red = world.t
  if (world.counts.red > 0) world.extinct.red = null
}

function kindSpeed(params: Params, b: Blob) {
  return (b.kind === 'blue' ? params.blueSpeed : params.redSpeed) * b.traits.speed
}

function kindVision(params: Params, b: Blob) {
  return (b.kind === 'blue' ? params.blueVision : params.redVision) * b.traits.vision
}

function growFruit(world: World, params: Params, dt: number) {
  for (const tree of world.trees) {
    if (tree.fruit > params.fruitLimit) tree.fruit = params.fruitLimit
    for (let i = 0; i < tree.slots.length; i++) {
      const target = i < tree.fruit ? 1 : 0
      const slot = tree.slots[i]
      if (slot.pop !== target) {
        slot.pop = target === 1 ? Math.min(1, slot.pop + dt * 3.2) : Math.max(0, slot.pop - dt * 5)
      }
    }
    if (tree.delay > 0) {
      tree.delay -= dt
      continue
    }
    if (tree.fruit >= params.fruitLimit) {
      tree.growth = Math.min(tree.growth, 0.999)
      continue
    }
    tree.growth += params.fruitGrowth * dt
    while (tree.growth >= 1 && tree.fruit < params.fruitLimit) {
      tree.growth -= 1
      tree.fruit++
      addEffect(world, {
        kind: 'ripen',
        x: tree.x,
        y: tree.y,
        z: 26 * tree.scale,
        life: 0.5,
        color: 'fruit',
        seed: tree.id * 31 + tree.fruit,
      })
    }
  }
}

function finishLockedAction(world: World, params: Params, b: Blob, rng: Rng) {
  if (b.action === 'eat') {
    b.energy = Math.min(CONST.maxEnergy, b.energy + CONST.fruitEnergy)
    b.meals++
    b.glow = 0.7
    b.squash = 0.55
    world.totals.fruitEaten++
    addEffect(world, { kind: 'eat', x: b.x, y: b.y, z: 10, life: 0.6, color: 'fruit', seed: b.id + world.steps })
    b.action = 'wander'
    b.actionTimer = 0
    b.targetTree = -1
  } else if (b.action === 'contact') {
    b.action = 'rest'
    b.actionTimer = params.redPause
    b.actionTotal = params.redPause
  } else if (b.action === 'rest') {
    b.action = 'wander'
    b.actionTimer = 0
    b.targetBlob = -1
    const a = rng.next() * TAU
    b.vx = Math.cos(a) * 3
    b.vy = Math.sin(a) * 3
  }
}

function steer(b: Blob, dx: number, dy: number, maxSpeed: number, dt: number, agility = 1) {
  const len = Math.hypot(dx, dy)
  let tx = 0
  let ty = 0
  if (len > 1e-6) {
    tx = (dx / len) * maxSpeed
    ty = (dy / len) * maxSpeed
  }
  const k = Math.min(1, CONST.turnRate * agility * dt)
  b.vx += (tx - b.vx) * k
  b.vy += (ty - b.vy) * k
  const sp = Math.hypot(b.vx, b.vy)
  if (sp > maxSpeed) {
    b.vx = (b.vx / sp) * maxSpeed
    b.vy = (b.vy / sp) * maxSpeed
  }
}

function applyMotion(world: World, b: Blob, dt: number) {
  b.x += b.vx * dt
  b.y += b.vy * dt
  const r = Math.hypot(b.x, b.y)
  const edge = world.radius - CONST.blobRadius - 2
  if (r > edge) {
    const nx = b.x / r
    const ny = b.y / r
    b.x = nx * edge
    b.y = ny * edge
    const dot = b.vx * nx + b.vy * ny
    b.vx -= nx * dot * 1.6
    b.vy -= ny * dot * 1.6
  }
}

function wanderVector(b: Blob, world: World, rng: Rng): { x: number; y: number } {
  if (rng.next() < 0.035) b.phase += rng.range(-0.9, 0.9)
  const drift = b.phase + Math.sin(world.t * 0.35 + b.id * 1.7) * 0.5
  let dx = Math.cos(drift)
  let dy = Math.sin(drift)
  const r = Math.hypot(b.x, b.y)
  const margin = world.radius * 0.82
  if (r > margin) {
    const push = (r - margin) / (world.radius - margin)
    dx -= (b.x / r) * push * 2.2
    dy -= (b.y / r) * push * 2.2
  }
  return { x: dx, y: dy }
}

function integrate(blob: Blob, wx: number, wy: number, maxSpeed: number) {
  const mag = Math.hypot(wx, wy)
  let tx = 0
  let ty = 0
  if (mag > 0.001) {
    tx = (wx / mag) * maxSpeed
    ty = (wy / mag) * maxSpeed
    blob.heading = Math.atan2(ty, tx)
  }
  blob.vx += (tx - blob.vx) * C.turn * DT
  blob.vy += (ty - blob.vy) * C.turn * DT
  const sp = Math.hypot(blob.vx, blob.vy)
  if (sp > maxSpeed) {
    blob.vx *= maxSpeed / sp
    blob.vy *= maxSpeed / sp
  }
  blob.x += blob.vx * DT
  blob.y += blob.vy * DT
}

function spend(blob: Blob, params: Params, world: World) {
  const upkeep = blob.kind === 'blue' ? params.blueUpkeep : params.redUpkeep
  const speed = Math.hypot(blob.vx, blob.vy)
  const cap = blob.kind === 'blue' ? params.blueSpeed : params.redSpeed
  const moving = cap > 0 ? Math.min(1, speed / cap) : 0
  let rate = upkeep * (C.idleFrac + (1 - C.idleFrac) * moving)
  if (blob.kind === 'red') {
    let near = 0
    for (const other of world.blobs) {
      if (other === blob || other.kind !== 'red') continue
      if (hypot2(other.x - blob.x, other.y - blob.y) < C.crowdRange * C.crowdRange) near++
    }
    rate += near * C.scramble * (1 + near * 0.12)
  } else {
    let near = 0
    for (const other of world.blobs) {
      if (other === blob || other.kind !== 'blue') continue
      if (hypot2(other.x - blob.x, other.y - blob.y) < C.sepRange * C.sepRange) near++
    }
    rate += near * 0.09
  }
  blob.energy -= rate * DT
}

function tryEat(blob: Blob, world: World, params: Params, rng: Rng) {
  if (blob.kind !== 'blue' || busy(blob)) return
  for (const tree of world.trees) {
    if (hypot2(tree.x - blob.x, tree.y - blob.y) > (C.eatReach + tree.canopy * 0.35) ** 2) continue
    let best = -1
    let bestD = Infinity
    for (let i = 0; i < tree.berries.length; i++) {
      const berry = tree.berries[i]!
      if (!berry.ripe) continue
      const d2 = hypot2(tree.x - blob.x, tree.y - blob.y)
      if (d2 < bestD) {
        bestD = d2
        best = i
      }
    }
    if (best < 0) continue
    const berry = tree.berries[best]!
    berry.ripe = false
    berry.grow = 0
    berry.cool = params.fruitDelay
    blob.energy = Math.min(C.maxEnergy, blob.energy + C.fruitEnergy)
    blob.meals++
    world.totals.eaten++
    setAction(blob, 'eat', params.blueEatTime)
    blob.squash = 1
    blob.glow = 1
    blob.vx *= 0.15
    blob.vy *= 0.15
    world.sparks.push(spark('eat', blob.x, blob.y, 'fruit', rng))
    return
  }
}

function tryContact(blob: Blob, world: World, params: Params, rng: Rng) {
  if (blob.kind !== 'red' || busy(blob)) return
  for (const other of world.blobs) {
    if (other.kind !== 'blue' || other.immunity > 0) continue
    const hiding = other.action === 'eat' || other.energy < params.blueCopy * 0.42
    const reach = hiding ? C.contactReach * 0.38 : C.contactReach
    if (hypot2(other.x - blob.x, other.y - blob.y) > reach * reach) continue
    const taken = Math.min(other.energy, params.redStrength)
    other.energy -= taken
    other.immunity = C.immunity
    other.squash = 0.7
    blob.energy = Math.min(C.maxEnergy, blob.energy + taken * C.contactKeep)
    blob.meals++
    world.totals.contacts++
    setAction(blob, 'contact', C.contactTime)
    blob.actionTimer = C.contactTime
    blob.glow = 1
    blob.squash = 1
    blob.vx *= 0.2
    blob.vy *= 0.2
    other.glow = 0.6
    world.sparks.push(spark('contact', (blob.x + other.x) / 2, (blob.y + other.y) / 2, 'red', rng))
    return
  }
}

function finishContact(blob: Blob, params: Params) {
  if (blob.kind === 'red' && blob.action === 'contact' && blob.actionTimer <= 0) {
    setAction(blob, 'rest', params.redPause)
  }
}

function tryCopy(blob: Blob, world: World, params: Params, rng: Rng) {
  if (busy(blob) || blob.copyCool > 0 || blob.age < 8 || blob.meals < 1) return
  if (world.blobs.length >= C.popCap) {
    world.peaked = true
    return
  }
  const need = blob.kind === 'blue' ? params.blueCopy : params.redCopy
  if (blob.energy < need) return
  const share = need * C.copyShare
  const tax = share * C.copyTax
  blob.energy -= share + tax
  blob.copyCool = C.copyCool
  blob.meals = 0
  blob.children++
  const jitter = rng.inDisc(10)
  const child = makeBlob(
    world.nextId++,
    blob.kind,
    blob.x + jitter.x,
    blob.y + jitter.y,
    share,
    inherit(blob.traits, rng),
    rng,
    blob.generation + 1,
    blob.id,
    blob.family,
  )
  child.copyCool = C.copyCool * 0.6
  world.blobs.push(child)
  world.totals.births[blob.kind]++
  world.sparks.push(spark('birth', blob.x, blob.y, blob.kind, rng))
}

function tickAnim(blob: Blob, rng: Rng) {
  blob.age += DT
  blob.copyCool = Math.max(0, blob.copyCool - DT)
  blob.immunity = Math.max(0, blob.immunity - DT)
  blob.glow = Math.max(0, blob.glow - DT * 1.8)
  blob.squash = Math.max(0, blob.squash - DT * 2.4)
  if (blob.actionTimer > 0) {
    blob.actionTimer = Math.max(0, blob.actionTimer - DT)
    if (blob.action === 'eat') blob.squash = 0.45 + Math.sin(worldless(blob) * 14) * 0.2
  }
  blob.blink -= DT
  if (blob.blinkFor > 0) {
    blob.blinkFor -= DT
  } else if (blob.blink <= 0) {
    blob.blinkFor = 0.12
    blob.blink = rng.range(1.4, 5.8)
  }
  const moving = Math.hypot(blob.vx, blob.vy)
  blob.hop = moving > 4 ? Math.abs(Math.sin(blob.age * 10 + blob.phase)) : blob.hop * 0.9
}

function worldless(blob: Blob) {
  return blob.age + blob.phase
}

function tickSparks(world: World) {
  for (const s of world.sparks) s.life -= DT
  world.sparks = world.sparks.filter((s) => s.life > 0)
}

export function step(world: World, params: Params, rng: Rng) {
  world.t += DT
  world.steps++
  growFruit(world, params)

  for (const blob of world.blobs) {
    tickAnim(blob, rng)

    if (busy(blob)) {
      blob.vx *= 0.55
      blob.vy *= 0.55
      blob.x += blob.vx * DT
      blob.y += blob.vy * DT
      if (blob.action === 'eat' && blob.actionTimer > 0) {
        blob.squash = 0.5 + Math.sin(blob.age * 16) * 0.22
      }
      finishContact(blob, params)
      if (blob.action === 'eat' && blob.actionTimer <= 0) setAction(blob, 'wander')
      if (blob.action === 'rest' && blob.actionTimer <= 0) setAction(blob, 'wander')
    } else {
      const steered = blob.kind === 'blue' ? steerBlue(blob, world, params, rng) : steerRed(blob, world, params, rng)
      const wall = keepInDish(blob, world.radius, steered.wx, steered.wy)
      const maxSpeed = (blob.kind === 'blue' ? params.blueSpeed : params.redSpeed) * blob.traits.speed
      integrate(blob, wall.wx, wall.wy, maxSpeed)
      tryEat(blob, world, params, rng)
      tryContact(blob, world, params, rng)
    }

    spend(blob, params, world)
    tryCopy(blob, world, params, rng)
  }

  const alive: Blob[] = []
  for (const blob of world.blobs) {
    if (blob.energy > 0) alive.push(blob)
    else {
      world.totals.deaths[blob.kind]++
      world.sparks.push(spark('pop', blob.x, blob.y, blob.kind, rng))
    }
  }
  world.blobs = alive
  tickSparks(world)
  recount(world)
}

export function pickBlob(world: World, x: number, y: number, reach = 14): Blob | null {
  let best: Blob | null = null
  let bestD = reach * reach
  for (const blob of world.blobs) {
    const d2 = hypot2(blob.x - x, blob.y - y)
    if (d2 < bestD) {
      bestD = d2
      best = blob
    }
  }
  return best
}

